<?php
require __DIR__.'/../config/app.php';$me=require_role('admin');$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$action=(string)($_POST['action']??'');if($action==='create_admin'){$name=trim((string)($_POST['name']??''));$email=strtolower(trim((string)($_POST['email']??'')));$password=(string)($_POST['password']??'');if($name===''||mb_strlen($name)>120||!filter_var($email,FILTER_VALIDATE_EMAIL)||!preg_match('/@marwadiuniversity\.ac\.in$/i',$email)||strlen($password)<8)$error='Enter a valid name, university email and password of at least 8 characters.';else try{$q=db()->prepare("INSERT INTO users(name,email,password_hash,role,is_active) VALUES(?,?,?,'admin',1)");$q->execute([$name,$email,password_hash($password,PASSWORD_DEFAULT)]);flash('Admin account created.');go('admin/admin-accounts.php');}catch(Throwable $t){$error='Could not create account. Check whether the email is already registered.';}}elseif($action==='set_status'){$error='Admin accounts cannot change another administrator account.';}}
$search=trim((string)($_GET['q']??''));$term='%'.$search.'%';$q=db()->prepare("SELECT id,name,email,is_active,created_at FROM users WHERE role='admin' AND (?='' OR name LIKE ? OR email LIKE ?) ORDER BY name");$q->execute([$search,$term,$term]);$rows=$q->fetchAll();if(($_GET['export']??'')==='csv'){header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename=\"eventhub-admin-accounts.csv\"');$out=fopen('php://output','w');fputcsv($out,['Name','Email','Status','Joined']);foreach($rows as $r)fputcsv($out,[$r['name'],$r['email'],$r['is_active']?'Active':'Inactive',$r['created_at']]);fclose($out);exit;}
$perPage=25;$totalRecords=count($rows);$totalPages=(int)ceil($totalRecords/$perPage);$currentPage=max(1,min($totalPages?:1,(int)($_GET['page']??1)));$rows=array_slice($rows,($currentPage-1)*$perPage,$perPage);$pageTitle='Admin Accounts';$bodyClass='dashboard-page admin-page';$activePage='users';$adminSection='users';require __DIR__.'/../includes/header.php';
?><div class="dash-layout admin-layout"><?php require __DIR__.'/../includes/sidebar.php';?><main class="content-page admin-content admin-events-page"><header class="admin-page-heading"><div><span class="admin-eyebrow">ACCOUNT DIRECTORY</span><h1>Admin Accounts</h1><p>Create admin access. Each administrator can edit only their own account; existing admin accounts are protected.</p></div></header><?php require __DIR__.'/section-nav.php';?><?php if($error):?><div class="inline-error"><?=e($error)?></div><?php endif;?><section class="admin-work-card"><div class="admin-card-heading"><span class="admin-heading-icon"><?=eventhub_icon('user')?></span><div><h2>Create admin account</h2><p>Use a Marwadi University email and a password of at least 8 characters.</p></div></div><form method="post" class="form-card admin-event-form"><input type="hidden" name="_csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="create_admin"><div class="admin-form-grid"><label>Name<input name="name" maxlength="120" required></label><label>Email<input type="email" name="email" pattern=".+@marwadiuniversity\.ac\.in" required></label><label>Temporary password<input type="password" name="password" minlength="8" required></label></div><div class="admin-form-actions"><span class="profile-role">Admin access applies across the admin panel.</span><button class="btn primary">Create Admin</button></div></form></section><section class="admin-work-card"><form method="get" class="admin-report-filters"><input name="q" value="<?=e($search)?>" placeholder="Search admin accounts"><button class="btn primary">Search</button><a class="btn outline" href="<?=url('admin/admin-accounts.php?'.http_build_query(['q'=>$search,'export'=>'csv']))?>">Export CSV</a></form><?php if($rows):?><div class="table-wrap admin-table-wrap"><table><thead><tr><th>Name</th><th>Email</th><th>Joined</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?=e($r['name'])?></strong><?=$r['id']==$me['id']?'<small>Current account</small>':''?></td><td><?=e($r['email'])?></td><td><?=date('d M Y',strtotime($r['created_at']))?></td><td><span class="admin-state <?=$r['is_active']?'published':'draft'?>"><?=$r['is_active']?'Active':'Inactive'?></span></td><td><div class="admin-row-actions"><?php if((int)$r['id']===(int)$me['id']):?><a href="<?=url('admin/account-edit.php?role=admin&id='.$r['id'])?>">Edit My Account</a><?php else:?><span class="muted">Protected account</span><?php endif;?></div></td></tr><?php endforeach;?></tbody></table></div><?php else:?><div class="empty">No matching admin accounts.</div><?php endif;?></section><?php require __DIR__.'/../includes/admin-pagination.php';?></main></div><?php require __DIR__.'/../includes/footer.php';
